-- The notable-NPC gap, first part: the named people of Rifts Dimension Book 2:
-- Phase World and Rifts Dimension Book 1: Wormwood - rows for notable_npcs
-- (migration 072) and their attacks in stat_attacks (owner_kind 'notable_npc').
--
-- One-off data script, run once per environment. NOT a migration.
--
-- FOUND by listing, in every cached book, the stat blocks that carry a Real /
-- True / Full Name line or a numeric experience level - the filing rule of
-- migration 072 - and removing the 243 notable NPCs already live. Phase 2a took
-- only one Phase World person (the Knife Master, whose Real Name line is Arno the
-- Freelancer - he is not added twice) and nothing from Wormwood, which was not yet
-- cached.
--
-- PHASE WORLD: the Notable Citizens of Center (Thraxus, Anshurr, Trader
-- Smythers), the Kreeghor Emperor, and the crew of the ship The Stick in Your Eye.
-- The Emperor's stats are printed as dice (he is "an average" emperor), so they
-- are in bonuses_note and his number columns are empty. Three more crew members
-- get one line and a level, but no stat block, and are not rows.
--
-- WORMWOOD: the three Non-Player Heroes (the Confessor, Lazarus Vespers, Dorsey
-- Pentecost), the Lords of Darkness (the Unholy, Lesion, Krikton, Salome) and The
-- Rock, the Great Horned Dragon of Rock Ridge.
--
-- A rank or office is the title, not the name (Bill Borshenko, not Captain Bill
-- Borshenko), as in #1164.
--
-- EXTRACTED by book-extract-workers, every number read off a 200 dpi render
-- rather than the OCR cache, which carries the digit cipher. RECONCILED by
-- book-reconcile against the renders, row by row; its corrections are applied.
-- description, disposition and natural_abilities are short paraphrases, checked
-- against the cache by an 8-word shingle test - no sentence is the book's.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-notable-npcs-phase-world-and-wormwood.sql
--
-- BY BOOK:
--   Rifts Dimension Book 2: Phase World (10): Thraxus, Anshurr, Trader Smythers,
--     Kreeghor Emperor, Bill Borshenko, Auntie, Murray, Bug, Laurana, Tiny Tim
--   Rifts Dimension Book 1: Wormwood (8): The Confessor, Lazarus Vespers, Dorsey
--     Pentecost, The Unholy, High Lord Lesion, Lord Krikton, Salome, The Rock

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'thraxus', 'Thraxus', NULL, 'Ruler of the Manors', 'rifts', NULL, 'Godling', 15, 'Anarchist with leanings toward miscreant.', NULL, NULL, NULL, '{"IQ":24,"ME":30,"MA":27,"PS":20,"PP":19,"PE":23,"PB":17,"Spd":16}', NULL, NULL, 684, 30, NULL, NULL, 9, '{"attacks":6,"initiative":3,"strike":4,"parry":10,"dodge":10,"roll":4,"pull":4}', '+10 save vs magic, +10 save vs poison and disease, +10 to save vs horror factor. Horror Factor 9 applies only to those who know of his reputation (awe). Supernatural attributes.', '[{"name":"Language: Dragonese/Elven","pct":98},{"name":"Demon and Monster Lore","pct":98},{"name":"Detect Ambush","pct":98},{"name":"Escape Artist","pct":98},{"name":"Prowl","pct":98},{"name":"Streetwise","pct":98},{"name":"Tracking","pct":98},{"name":"Wilderness Survival","pct":98}]', 'Also has all Trade Languages of the Three Galaxies plus a half dozen more from different worlds at 98% (individual languages not named). Hand to Hand: Expert.', 'See the invisible and turn invisible at will, resistant to poison/drugs/toxins (half effective), nightvision 200 ft (61 m), fire and cold resistant (half damage), regenerates 1D6x5 M.D.C. per minute, fires energy blasts doing 8D6 M.D. (range 1000 ft/305 m).', 'None, but has extensive knowledge of magic lore, weapons and artifacts; owns dozens of magical items with spell-casting abilities and combat properties.', NULL, NULL, NULL, 'Half a dozen greatest rune weapons, two dozen greater rune weapons, and nearly a hundred magical weapons of all types from over a hundred dimensions, including artifacts inflicting 2D6x10 M.D. per attack and force fields with 1,000 M.D.C. Wears a half dozen rings plus earrings, necklaces and armbands making him invulnerable to magic, most energy attacks, and psionics, and letting him teleport to a safe haven (equal to the superior teleport spell).', 'Liquid assets over 100 trillion credits; other holdings and properties probably worth 50 to 100 times as much.', 'A master schemer who plays life for sport and relishes matching wits with a capable rival.', 'Extensive contacts with Naruni Enterprises and other Three Galaxies corporations; former dungeon-crawling companions now powerful magicians, planetary rulers and other influential figures; bodyguards Saburo (horned dragon hatchling, 5th level), Doodles (tattooed man, 8th level), Total Eclipse (silhouette sorcerer, 9th level), Crimson (kreeghor renegade, 7th level); a personal army of at least 500 soldiers.', 'Has foiled the Splugorth several times and is targeted by Sunaj assassins and other Splugorth minions; also the nemesis of many champions of light.', 'A godling posing as the wealthiest business magnate in the Three Galaxies, ruling the Manors level of Center from his White Tower.', 'Rifts Dimension Book 2: Phase World p.20-22');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'anshurr', 'Anshurr', NULL, 'The Eye of Klynncryth', 'rifts', 'Splugorth', 'High Lord', 10, 'Diabolic', NULL, NULL, NULL, '{"IQ":22,"ME":20,"MA":11,"PS":32,"PP":21,"PE":18,"PB":3,"Spd":24}', NULL, NULL, 300, 300, 60, NULL, 14, '{"attacks":5,"initiative":1,"strike":4,"parry":4,"dodge":4,"roll":2,"pull":2}', 'Five physical attacks per melee round, or two by magic. +2 save vs magic, +1 save vs poison and disease, +8 to save vs horror factor. Takes double damage from certain holy and magic weapons. Supernatural strength and endurance.', '[{"name":"Biology","pct":98},{"name":"Astronomy","pct":98},{"name":"Chemistry","pct":98},{"name":"Pathology","pct":98},{"name":"Holistic Medicine","pct":98},{"name":"Basic Math","pct":98},{"name":"Advanced Math","pct":98},{"name":"Computer Operation","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Radio: Scrambler","pct":98},{"name":"Intelligence","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Faerie","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Trade One","pct":98},{"name":"Language: Trade Two","pct":98},{"name":"Language: Trade Three","pct":98},{"name":"Language: Trade Four","pct":98},{"name":"Language: Trade Five","pct":98},{"name":"Language: Trade Six","pct":98},{"name":"Language: Atlantean","pct":98}]', 'Combat abilities: Natural.', 'Nightvision 1000 ft (305 m), excellent color vision, turn invisible at will, see the invisible, bio-regenerate 1D4x10 M.D.C. per minute, dimensional teleport 98% to his master only, as often as once every 24 hours.', 'Knows all spells and ritual knowledge from levels 1-13, plus all stone master powers, the power to create magic tattoos, and bio-wizardry.', 'Major psionic: astral projection, empathy, mind block, object read, sense magic, speed reading, telepathy and total recall, all equal to a 10th level psychic.', NULL, NULL, 'A lesser rune sword (5D6 M.D.) with all the usual powers, a psi-interrogator, and a staff of pacification. Standard High Lord armor (100 M.D.C.).', 'Can get his hands on 1D4x100 million credits at a moment''s notice, and can request more funds from Lord Klynncryth.', 'A master of understated intimidation who rarely threatens directly, remains calm with underlings, but does not tolerate failure.', 'Lord Klynncryth (his master); closest friend is a Raksasha demon named Zabranas; commands Sector 3-A security forces (thousands of kittani and kydian warriors, tattooed men, metzla monsters); a small army of spies, bodyguards and special agents; favors human, renegade Atlantean, elf and other lesser-race agents.', 'Thraxus and Naruni Enterprises, longtime rivals of the Splugorth.', 'A Splugorth High Lord serving as Lord Klynncryth''s chief of intelligence and counter-espionage in Center and the Three Galaxies.', 'Rifts Dimension Book 2: Phase World p.22-23');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'trader-smythers', 'Trader Smythers', NULL, 'Naruni Enterprises', 'rifts', 'Uteni', 'Alien Merchant', 10, 'Aberrant', NULL, NULL, NULL, '{"IQ":20,"ME":15,"MA":23,"PS":12,"PP":15,"PE":16,"PB":18,"Spd":11}', 51, 243, NULL, 20, 86, NULL, NULL, '{"attacks":4,"strike":1,"parry":2,"dodge":2,"roll":4,"pull":4}', 'Attacks Per Melee Round: Four. +3 to save vs horror factor. M.D.C.: By armor or force field only (printed value, not a number). Horror Factor printed as None.', '[{"name":"Computer Hacking","pct":98},{"name":"Computer Programming","pct":98},{"name":"Galactic Lore","pct":98},{"name":"Demon and Monster Lore","pct":98}]', 'Speaks all trade languages and a dozen other languages of the Three Galaxies (no percentages given). W.P. Energy Pistol, W.P. Energy Rifle. Hand to Hand: Basic.', 'Uteni shape-changer: his true form is a tall (about 8 ft/2.4 m), thin, hairless, blue-skinned biped with big eyes and no mouth or nose (he breathes through his skin); he can reshape into any two-legged form 4 to 9 ft (1.2 to 2.7 m) tall at the same weight, but cannot grow hair or change his blue coloring.', NULL, 'Clairvoyance, mind block and see aura.', NULL, NULL, 'Several handguns (all manufactured by N.E.). Personal Force Field (130 M.D.C.).', 'Personal fortune of 900 million credits, plus trillions of credits available through Naruni Enterprises.', 'Salesman-friendly only while it pays; he will drop anyone for a better deal.', 'Full support of Naruni Enterprises; loosely affiliated with the Society of the Knife and other criminals; a personal bodyguard of fanatically loyal kreeghor renegades.', 'Thraxus (mutual distrust; once sent a hit team that was returned to him in pieces) and the Splugorth.', 'A Uteni trader in charge of Naruni Enterprises Free Trade Zone operations, including its black-market dealings, in Center.', 'Rifts Dimension Book 2: Phase World p.23');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'kreeghor-emperor', 'Kreeghor Emperor', NULL, 'NPC Villain', 'rifts', 'Kreeghor', NULL, NULL, 'Any evil', NULL, '12 to 15 feet (3.6 to 4.6 m) fully erect, but tends to crouch.', '700 lbs (315 kg)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, '{"initiative":4,"strike":2,"parry":4,"dodge":4,"roll":2,"pull":3}', '+1 save vs magic, +10 to save vs horror factor, all in addition to skill and attribute bonuses. Magic, magic weapons and holy items inflict double damage; rune weapons inflict triple damage; weapons from a Millennium Tree inflict ten times damage. Printed as dice, not fixed numbers: Attributes I.Q. 3D6+6, M.E. 3D6+10, M.A. 3D6+10, P.S. 5D6+20 (supernatural), P.P. 3D6+10, P.E. 3D6+10, P.B. 2D4, Spd. 4D6+40. M.D.C.: 2D6x100+500 plus 1D6x100 per level of experience. P.P.E.: 2D4x100. I.S.P.: 4D6x10 plus M.E. attribute and 20 per level. Experience Level: 1D6+3 (average). Average Life Span: 1,000+ years. Combat: equivalent to Hand to Hand: Assassin.', '[{"name":"Literacy: Trade Five","pct":98}]', 'R.C.C. Skills and R.C.C. Related Skills printed as Same as the Royal Kreeghor (the entry immediately before this one on the same page): includes Basic Radio, Computer Operation, Power Armor: Elite, Fighter Combat: Elite, Pilot: Two of Choice, Weapon Systems, W.P.: Any two, Hand to Hand: Assassin, plus 8 selectable R.C.C. Related skills and category-access lists given with percentage bonuses rather than raw percentiles.', 'See the invisible, impervious to mind control, impervious to disease, resistant to all known drugs and magic potions (one-third damage, effect and duration), bio-regenerate 2D6x10 M.D.C. per minute (four melees), regrow lost limbs, eyes and organs in 1D4 hours.', 'Magically knows all first level spells plus sanctum, close Rift, dimensional portal and teleport superior; each subsequent level magically knows six additional spells selected from levels 1-10. Cannot learn or purchase spells normally.', 'Considered a master psionic. Initially knows all sensitive and physical category powers, plus two super psionic powers; gains two more powers from the healing or super psionic categories per subsequent level of experience.', NULL, NULL, 'The Sword of Kreeghor (a greatest rune sword), a Splugorth staff of pacification, and any energy weapons of choice. Kreeghor battle armor (giant-sized, M.D.C. 140) or power armor and force fields, though typically wears none.', NULL, 'A god-like tyrant wielding overwhelming magic and psionic power, so secure in his strength he rarely bothers with armor.', 'The Royal Kreeghor, most members of the kreeghor race, and loyal subjects, who will give their lives for him.', NULL, 'The supremely powerful ruler of the Kreeghor race and the Transgalactic Empire, wielding magic, psionics and immense M.D.C.', 'Rifts Dimension Book 2: Phase World p.76-77');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'borshenko', 'Bill Borshenko', 'William Giacomo Borshenko', 'Captain of The Stick in Your Eye', 'rifts', 'Human', 'CAF Fleet Officer', 8, 'Unprincipled', NULL, NULL, NULL, '{"IQ":17,"ME":14,"MA":20,"PS":17,"PP":19,"PE":17,"PB":17,"Spd":21}', 46, 36, NULL, 6, 36, NULL, NULL, '{"attacks":6,"initiative":1,"strike":4,"parry":7,"dodge":7,"roll":4,"pull":4}', '+1 save vs magic, +1 save vs psionics, +2 save vs horror factor. M.D.C. printed as "By armor only" (no number). Horror Factor printed literally as "n/a". The book gives a single "+4 to roll/pull punch" bonus applied to both roll and pull here.', '[{"name":"Detect concealment","pct":83},{"name":"Intelligence","pct":87},{"name":"Paramedic","pct":98},{"name":"Demolition","pct":97},{"name":"Pilot spaceship","pct":98},{"name":"Prowl","pct":73},{"name":"Alien lore","pct":73}]', 'Hand to hand: martial arts and boxing. W.P. Energy pistol, energy rifle, heavy energy, power armor combat: basic, fighter pilot: basic.', NULL, NULL, 'Minor Psionic: bio-regenerate and deaden pain.', NULL, NULL, 'NE-4P plasma cartridge pistol (1D4x10 M.D.), HI-80 laser rifle; CAF Combat armor (M.D.C. 100).', 'Personal fortune of one million credits in cash, one million in various stocks, plus his investment in the ship.', 'A self-driven leader who takes the riskiest jobs himself rather than delegate; a well-known ladies'' man whose romances tend to cause trouble.', 'The crew of the Stick, plus contacts among runners, black markets, and various adventurers, travelers and spies of the Three Galaxies, including Phase World.', 'The Transgalactic Empire, which condemned him to death in absentia.', 'Captain of the smuggler ship the Stick in Your Eye, a rebellious ex-CAF officer turned runner, wanted on several worlds and condemned to death in absentia by the Transgalactic Empire. Muscular, blond, blue-eyed and Nordic-looking; his beard, moustache or stubble changes with his mood.', 'Rifts Dimension Book 2: Phase World p.177-178');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'auntie', 'Auntie', NULL, NULL, 'rifts', 'Machine People', 'Machine People R.C.C. (altered)', 10, 'Unprincipled', NULL, NULL, NULL, '{"IQ":30,"ME":20,"MA":22}', NULL, NULL, 400, 0, NULL, NULL, 10, '{"attacks":8,"initiative":3,"strike":9,"dodge":10}', '+3 to save vs magic and psionics, +6 to save vs horror factor; impervious to disease, gases and other maladies that afflict humanoids. Horror Factor of 10 is specifically for people who realize she is a sentient starship. Damage varies with weapon system (see the ship''s stats) so no fixed combat.damage is given. Destroying the starship carries a 1-21% chance of also destroying her mind. The book gives her holographic projection a P.B. of 14, which is not a physical attribute of Auntie herself ("most physical attributes are meaningless" per the text) and is not included in the attributes block. Vulnerable: she has no body outside the starship; her holograms (up to 1 mile/1.6 km from the ship) are insubstantial and can only make light and sound.', '[{"name":"Astrophysics","pct":98},{"name":"Navigation: space","pct":98},{"name":"Read sensory equipment","pct":98},{"name":"Computer operation","pct":98},{"name":"Computer programming","pct":95},{"name":"Xenology","pct":95},{"name":"Streetwise","pct":62},{"name":"Lore: aliens","pct":98},{"name":"Piloting: starship","pct":98}]', NULL, 'Rather than the usual machine-people powers, she is merged with the starship: its sensors, guns and computers are hers to use, and she flies it with remarkable speed and skill.', NULL, NULL, NULL, NULL, 'See the Stick In Your Eye''s weapon systems.', NULL, 'Sees herself as the crew''s surrogate parent, always available for advice or comfort, but shy and distrustful of strangers; has no patience for sloppiness, and dislikes Borshenko''s love interests out of a crush on him.', 'Captain Borshenko and the crew of the Stick.', 'The pirates who once enslaved her (destroyed when she took back her ship).', 'The sentient artificial intelligence of the Stick in Your Eye - a Machine People whose original body was destroyed by pirates, now bonded permanently to the ship she pilots.', 'Rifts Dimension Book 2: Phase World p.178-179');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'murray', 'Murray', NULL, 'First Mate', 'rifts', 'Seljuk', 'Headhunter', 7, 'Anarchist', NULL, NULL, NULL, '{"IQ":13,"ME":17,"MA":14,"PS":46,"PP":18,"PE":22,"PB":9,"Spd":20}', NULL, NULL, 270, 4, NULL, NULL, 11, '{"attacks":5,"initiative":2,"strike":4,"parry":7,"dodge":7,"roll":4,"pull":4}', '+7 save vs magic. The book gives a single +4 to roll/pull punch bonus applied to both roll and pull here. Only an M.D.C. figure (270) is printed, no separate S.D.C./Hit Points line.', '[{"name":"Basic radio","pct":95},{"name":"Detect ambush","pct":75},{"name":"Detect concealment","pct":75},{"name":"Tracking","pct":70},{"name":"Weapon systems","pct":85},{"name":"Pilot starship","pct":83}]', 'Hand to hand: expert, boxing and wrestling.', 'Takes half damage from M.D.C. fire and energy attacks (including magical attacks); regenerates 1D6x10 M.D.C. per hour; excellent sense of smell.', NULL, NULL, NULL, NULL, 'Power halberd, HI-80 laser rifle, and an assortment of heavy energy weapons; modified suit of Kittani Explorer Armor (M.D.C. 85).', 'Personal fortune of 500,000 credits in addition to his weapons and possessions.', 'A former street enforcer slowly learning to trust others; fiercely loyal to Borshenko, Auntie and Laurana, but reverts to bullying and intimidation with hostile strangers and will kill to protect his teammates.', 'Borshenko (his closest friend), Auntie, Laurana, and the rest of the Stick''s crew.', 'The Transgalactic Empire, whose penal colony he escaped.', 'The Stick''s first mate, a powerful and nearly-invulnerable Seljuk ex-convict and former killer-for-hire who became Borshenko''s closest friend in a Transgalactic Empire penal colony.', 'Rifts Dimension Book 2: Phase World p.179');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'bug-vacuum-wasp', 'Bug', NULL, 'Vacuum Wasp Pilot', 'rifts', 'Vacuum Wasp', NULL, 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":11,"ME":10,"MA":16,"PS":21,"PP":22,"PE":18,"PB":6,"Spd":23}', NULL, NULL, 200, 11, 160, NULL, 10, '{"attacks":6,"initiative":2,"strike":9,"parry":9,"dodge":9,"roll":2,"pull":2}', '+2 to dodge while flying (total +7 to dodge while flying), +2 to engage in dog-fighting, +4 save vs magic, +6 save vs horror factor. Takes double damage from psionic attacks. Speed 23 is running only; also Mach 6 in an atmosphere and Mach 10 in space. M.D.C. 200 plus a separate N-F50A Force Field of 160 M.D.C. The book gives a single +2 to roll/pull punch bonus applied to both roll and pull here.', '[{"name":"Navigation: space","pct":80},{"name":"Pilot starship","pct":78},{"name":"Weapon systems","pct":80}]', 'W.P. energy rifle.', 'Multi-spectrum vision equivalent to a cybernetic multi-optic eye and radar (range 2000 feet/610 m); regenerates lost limbs and M.D.C. at 1D4x10 M.D.C. per 8-hour rest period; psionically recognizes members of his own Hive and instinctively attacks all others; supersonic flight up to Mach 6 in an atmosphere, Mach 10 in space; bio-electric blast (3D6 M.D. at level one plus 1D6 per additional level, range 4000 feet/1200 m).', NULL, 'See aura, see the invisible, sense magic, and mind-block auto-defense; plus telepathy that costs no I.S.P. but only works between Hive members.', NULL, NULL, NULL, NULL, 'Silent like all Star Wasps, he pays attention only to the crew and says little; the ship is his new hive and Auntie its queen, and he is closer to the vessel than anyone aboard.', 'The crew of the Stick, especially the ship itself and Auntie.', 'The Kittani, who destroyed his home Star Hive.', 'A twelve-foot insectoid Vacuum Wasp, sole survivor of a Star Hive destroyed by a Kittani fleet, adopted by the Stick''s crew after helping them fight off the same Kittani armada.', 'Rifts Dimension Book 2: Phase World p.179-180');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'laurana', 'Laurana', NULL, NULL, 'rifts', 'Alien (D-Bee, unspecified race)', 'alien temporal warrior', 8, 'Unprincipled', NULL, NULL, NULL, '{"IQ":22,"ME":21,"MA":19,"PS":11,"PP":17,"PE":25,"PB":17,"Spd":25}', 49, 120, NULL, 140, NULL, NULL, NULL, '{"attacks":4,"initiative":1,"strike":4,"parry":7,"dodge":7,"roll":5,"pull":5}', 'Four hand to hand attacks, or two by magic. +1 save vs magic, +3 save vs psionics, +5 save vs horror factor. M.D.C. printed as "By body armor or magic" (no number). Horror Factor printed literally as "None".', '[{"name":"Prowl","pct":88},{"name":"Pick locks","pct":88},{"name":"Land navigation","pct":96},{"name":"Wilderness survival","pct":88},{"name":"Swimming","pct":98},{"name":"Climbing","pct":88},{"name":"Basic math","pct":98},{"name":"Demon and monster lore","pct":73},{"name":"Language: American","pct":98},{"name":"Language: Trade One","pct":98},{"name":"Language: Trade Four","pct":98},{"name":"Language: Trade Five","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Dragonese","pct":98},{"name":"Language: Elf","pct":98}]', 'Sniper (W.P.). Hand to hand: martial arts and boxing.', 'Nightvision 200 feet (60 m); heightened mental abilities and physical endurance (attributed to her race).', 'Temporal magic (see Rifts England): D-phase, wink-out, dimensional pockets, see dimensional anomaly, s-dep, t-dep, time warp: age, time warp: fast forward, time warp: slow motion. Common magic: globe of daylight, tongues, see the invisible, detect concealment, armor of Ithan, invulnerability.', NULL, NULL, NULL, 'Kittani plasma ejector (6D6 M.D.); K-EP pump pistol (5D6 M.D.); Techno-wizard body armor (M.D.C. 80) with armor of Ithan enchantment (60 M.D.C.).', '200,000 credits in cash.', 'A gentle, sensitive woman hiding beneath a tough, boisterous facade; secretly despises violence and prefers to solve problems without firing a shot, though the crew relies on her rough humor and quiet kindness.', 'The crew of the Stick, especially Murray, whom she treats with kindness and respect.', 'The temporal raider who once owned her as a slave-warrior.', 'An exotically beautiful alien D-Bee temporal warrior and mage, the only crew member not native to the Three Galaxies, who escaped a temporal raider''s slavery to buy a share of the Stick.', 'Rifts Dimension Book 2: Phase World p.180-181');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'tiny-tim', 'Tiny Tim', 'Gannell A''Krytop', 'Promethean Science & Medical Officer', 'rifts', 'Promethean', NULL, 8, 'Scrupulous', NULL, NULL, NULL, '{"IQ":24,"ME":19,"MA":21,"PS":28,"PP":11,"PE":25,"PB":8,"Spd":11}', 161, 523, NULL, 110, 175, NULL, 10, '{"attacks":3,"initiative":1,"strike":1,"parry":2,"dodge":2,"roll":2,"pull":2}', 'Three hand to hand, psionic, or phase attacks/actions per melee. +11 save vs magic, +5 save vs psionics, +8 save vs horror factor. Takes double damage from phase and magic weapons. M.D.C. printed as "By body armor or magic only" (no number). The book gives a single +2 to roll/pull punch bonus applied to both roll and pull here.', '[{"name":"Language: Promethean","pct":98},{"name":"Literacy: Promethean","pct":98},{"name":"Language: Trade Two","pct":95},{"name":"Literacy: Trade Two","pct":95},{"name":"Language: Trade Four","pct":95},{"name":"Literacy: Trade Four","pct":95},{"name":"Language: Trade Five","pct":95},{"name":"Literacy: Trade Five","pct":95},{"name":"Basic and advanced math","pct":98},{"name":"Archeology","pct":85},{"name":"Biology","pct":95},{"name":"Botany","pct":90},{"name":"Chemistry","pct":95},{"name":"Computer operations","pct":98},{"name":"Analytical chemistry","pct":90},{"name":"Medical doctor","pct":98},{"name":"Pathology","pct":95},{"name":"Phase technology","pct":95}]', 'Hand to hand: basic. W.P. energy rifle and energy pistol.', 'Does not breathe air; immune to radiation and normal heat and cold; sees in total darkness; eagle-like normal vision; phase powers as per the Promethean R.C.C.', NULL, 'Astral projection, clairvoyance, deaden pain, empathy, object read, induce sleep, levitation, psychic diagnosis, psychic purification, psychic surgery, summon inner strength, telepathy, total recall, and mind block auto-defense; plus any three powers from the Healing, Sensitive or Physical categories, with one more power from any of those categories added every level after the first.', 'Phase Powers: D-shift ghost, dimensional leap, multiphase and phase field.', NULL, NULL, NULL, 'In a constant state of friendly curiosity, always eager to examine a mystery even at the risk of trouble; a skilled diplomat who puts people at ease despite his intimidating appearance.', 'The crew of the Stick.', 'A powerful lord of the United Worlds of Warlock, who hired thieves and assassins to pursue him.', 'The Stick''s Promethean science and medical officer, who joined the crew after hiring them to transport magical artifacts and being impressed by their quiet efficiency under attack.', 'Rifts Dimension Book 2: Phase World p.181');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'confessor', 'The Confessor', NULL, NULL, 'rifts', NULL, 'Apok', 11, 'Scrupulous', NULL, NULL, NULL, '{"IQ":17,"ME":19,"MA":17,"PS":32,"PP":21,"PE":14,"PB":15,"Spd":33}', NULL, NULL, 306, 136, NULL, NULL, 16, '{"attacks":6,"initiative":1,"strike":5,"parry":6,"dodge":6,"pull":2,"roll":2,"damage":20}', 'Horror Factor 16 only when wearing the mask. All attacks do double damage (O.C.C./mask power). +2 to save vs psionic attack, +2 to save vs magic, +2 to save vs poison and disease. Impervious to mind control, impervious to possession, and impervious to horror factor. Critical strike or knockout on an unmodified roll of 18-20. Meditation is the same as the priest. Printed as a combined ''Hit Points/M.D.C.: 306'' line.', '[{"name":"Intelligence","pct":82},{"name":"Disguise","pct":85},{"name":"Escape","pct":90},{"name":"Tracking","pct":90},{"name":"Language: American","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Gobblely","pct":98}]', 'All the usual skills from the Apok O.C.C., all at 98% (not individually itemized). Also boxing, paired weapons, W.P. targeting, W.P. sword, W.P. energy rifle (no percentages printed). Combat Abilities: Expert.', NULL, 'Communion with Wormwood/Priestly magic powers, same as all apok: create and close openings, hell fire (3D4x10 M.D.), impervious to symbiotes, repel symbiotes, plus create stairs and destroy life force cauldron.', NULL, NULL, NULL, 'Standard Equipment: travelling clothes, two hooded cloaks, two sets of clothing, boots, gloves, a hat, sleeping bag, blanket, 4 small pouches, backpack, 2 utility belts, first-aid kit, six blood worms, 30 worms of mending, 100 feet of rope (angel hair), a grappling hook, 4 resin spikes, 2 weeks of food rations. Armor: Light armor, 25 M.D.C., mainly for show. Magic Items of Note: nothing of note at this time.', 'Not applicable.', 'Iron-willed, self-assured and inventive, with a single-minded fixation - at present, wiping out the Forces of Darkness.', NULL, 'The Unholy (his personal nemesis); the corrupt high priests of the Cathedral.', 'The most famous and feared apok on Wormwood, a masked loner and monster-slayer whose crusade against the Unholy has become legend.', 'Rifts Dimension Book 1: Wormwood p.77-78');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'lazarus-vespers', 'Lazarus Vespers', NULL, NULL, 'rifts', NULL, 'Ley line walker/spell caster', 10, 'Scrupulous', NULL, NULL, NULL, '{"IQ":19,"ME":20,"MA":18,"PS":14,"PP":17,"PE":20,"PB":17,"Spd":12}', 60, 20, NULL, 188, 80, NULL, NULL, '{"attacks":4,"initiative":1,"strike":2,"parry":2,"dodge":2,"pull":2,"roll":2}', 'Attacks: four by hand to hand or psionics, or two by magic. Critical strike on unmodified 19 or 20. +7 to save vs magic, +3 to save vs psionic attack, +3 to save vs poison and disease, +4 to save vs horror factor. He is not a mega-damage being (S.D.C./Hit Points).', NULL, 'All the usual skills from the line walker O.C.C., all at 98% (not individually itemized). Combat Abilities: Basic.', NULL, 'Ley line walker from another dimension; possesses all ley line walker powers plus spells: globe of daylight, cloud of smoke, chameleon, see the invisible, breathe without air, swim as the fish, armor of Ithan, charismatic aura, cure minor disorders, purification, water to wine, ley line transmission, memory bank, magic pigeon, tongues, magic net, energy bolt, ignite fire, fire ball, circle of flame, escape, time slip, constrain being, turn dead, negate magic, transferal, close rift, and open dimensional portal.', 'Major psionic: exorcism, psychic diagnosis, healing touch, telekinesis, object read, mind block.', NULL, NULL, 'Wilk''s laser pistol (concealed), a silver plated dagger, a blue-grey lesser rune sword (5D6 M.D., adds +1 to ALL saving throws, indestructible, I.Q. of 11), one finder crystal, one light crystal, two lesser energy cells (25 P.P.E. each), 2D4 magic potions (G.M.''s choice). Armor: None. Standard Equipment: Standard. Transportation: usually walks.', 'Not applicable.', 'Clever and guarded; capable of leading others, he prefers not to.', 'Has fought alongside the Confessor, though does not consider him a friend; befriended various wormspeakers and monks.', 'Queen Salome (old friend turned nemesis, in a complicated love/duty conflict).', 'A mysterious wandering wizard-warrior who intervenes in battles against evil and is bound by history and guilt to his old friend, the evil Queen Salome.', 'Rifts Dimension Book 1: Wormwood p.79-80');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'dorsey-pentecost', 'Dorsey Pentecost', NULL, 'Captain, Knights of the Hospital', 'rifts', NULL, 'Knight of the Hospital', 7, 'Scrupulous', '24', NULL, NULL, '{"IQ":15,"ME":21,"MA":23,"PS":20,"PP":22,"PE":14,"PB":19,"Spd":28}', NULL, NULL, 94, 50, NULL, NULL, NULL, '{"attacks":5,"initiative":1,"strike":6,"parry":7,"dodge":7,"pull":3,"roll":3}', '+2 to save vs horror factor, +2 to save vs magic, +3 to save vs psionic attack, +2 to save vs disease. 75% to evoke trust or intimidation, 45% to charm. Recognizes poisons, drugs and magic potions/slime 40% + 5% per level of experience. Meditation is the same as the priest. Combat Abilities: Martial artist and paired weapons (taught the basics by the monks, but no special mastery powers). Printed as a combined ''Hit Points/M.D.C.: 94'' line.', '[{"name":"Horsemanship (general animal riding)","pct":59},{"name":"Pilot motorcycle","pct":94},{"name":"Land navigation","pct":80},{"name":"Wilderness survival","pct":75},{"name":"Paramedic","pct":90},{"name":"Biology","pct":70},{"name":"Lore: demons & monsters","pct":75},{"name":"Lore: Wormwood","pct":75},{"name":"Math: basic","pct":90},{"name":"Language: American","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Streetwise","pct":50},{"name":"Play the guitar","pct":80},{"name":"Dance","pct":75}]', 'Also boxing, W.P. targeting, W.P. knife, W.P. Sword, W.P. black powder TW pistol, W.P. energy pistol (no percentages printed).', NULL, 'Only lore skills (no spellcasting).', NULL, NULL, NULL, 'Travelling clothes, dress clothes and dress body armor (medium, 40 M.D.C.), boots, gloves, a hat, sleeping bag, blanket, 2D4 small pouches, saddle-bag, 3 utility belts, first-aid kit, six blood worms, 40 worms of mending, 100 feet of rope (angel hair), a grappling hook, 6 resin spikes, 4 weeks of food rations. Magic Items of Note: a cat''s eye bloodstone, a healing blood stone, a lesser energy crystal (25 P.P.E.). Knight Armor: Light armor, 25 M.D.C. Transportation: Harley Davidson motorcycle (family heirloom) plus two back-up TW-modified bikes (25 P.P.E. = one tank of gas / ~200 miles).', 'Not applicable; supported through the community''s respect for knights of the Hospital (lodging, food, access to buildings).', 'Born to lead but still young in it - over-eager, rash and blunt; inquisitive, principled and likeable.', 'The monks and younger knights of the Hospital; on friendly terms with at least one apok.', 'The Knights of the Temple, corrupt Cathedral authorities, and his uncle Matthew Pentecost (strained relationship).', 'The youngest Captain in Hospitaller history, a charming and rebellious knight loved by his fellow monks and knights but at odds with his noble family and the Temple.', 'Rifts Dimension Book 1: Wormwood p.81-82');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'unholy', 'The Unholy', NULL, 'Supreme Ruler of The Host and the Lord of Darkness', 'rifts', 'Host', NULL, 11, 'Miscreant', NULL, '15 feet tall (4.6 m)', '1400 pounds (630 kg)', '{"IQ":21,"ME":25,"MA":23,"PS":51,"PP":19,"PE":21,"PB":3,"Spd":27}', NULL, NULL, 6100, 900, 800, NULL, 19, '{"attacks":7,"initiative":1,"strike":6,"parry":5,"dodge":5,"pull":4,"roll":4}', 'Speed also 70 flying (~50 mph/80 km) vs 27 running (18 mph/29.7 km). +2 save vs psionics, +4 to save vs spell and illusionary magic, +3 to save vs circle magic, +1 to save vs all other magic, +10 to save vs horror factor. Critical strike on unmodified 18-20; hands/finger claws used as paired weapons. Eyes are small and hard to target: attacker must make a called shot, -4 to hit the large eyes and -6 to hit the tiny ones (he lost his large left eye to the Confessor and wears a patch sewn into his flesh). Level of Experience 11th applies equally to spell magic, communion with Wormwood spells, and psionic powers. Combat abilities equal to hand to hand: expert.', NULL, 'R.C.C. Skills (same as the Host): minimal skill knowledge; can learn to read/write up to four languages and 1D4 other technical skills; knows basic math, literate in American, land navigation, streetwise, cryptography, forgery, palming, concealment, prowl, dance, horsemanship: monsters, all at 85% (not individually broken out here).', 'Same as the Host: 10-13 foot wolf-headed, bull-horned, bat-winged giant with four eyes, skeletal clawed hands, and a bony exposed spine (the Unholy himself is 15 feet, 20% larger than typical Host).', 'Special ability to warp and shape nature/power over Wormwood, same as the Host, with the following communion-with-Wormwood spells: Close an Opening, Create Life Force Cauldron, Create Magic Slime, Create an Opening, Create a Pillar, Create Stairs, Create Tunnel, Create Wall, Create Worm Zombies, Destroy Life Force Cauldron, Impervious to Symbiotes, Mold Structures, Open & Close Dimensional Rifts, Remove Symbiotes, Repel Symbiotes, Ride Giant Parasites, Summon Entities, Summon and Command Parasites, Summon & Use Symbiotes (and redesign/create new types). Special Power - The Black Abyss Dimensional Pocket: a one-way stasis prison for one victim; only usable by the leader of the Host and his second-in-command; P.P.E. Cost 500; duration 1D4 days/level of creator (one decade/level on a ley line, one century/level at a nexus); only the creator can freely retrieve a prisoner (shifter 17%, temporal warrior 21%, temporal wizard 37%, temporal raider 69% chance for others, raider escapes instantly, others in 2D4 days).', 'Master psionic: astral projection, clairvoyance, empathy, telepathy, see aura, total recall, detect psionics, psychic diagnosis, psychic surgery (used to torture), healing touch, deaden pain, sleep, mind block auto-defense, group mind block, bio-manipulation, empathic transmission, hypnotic suggestion, mentally possess others, psi-sword, pyrokinesis.', NULL, NULL, 'A powerful magic scepter (see attacks). Crimson plate armor with black trim and a chain mail skirt, adding 100 M.D.C., worn mostly as ornamentation; a necklace of humanoid skulls.', 'A treasure stash worth 100 million credits on Rifts Earth.', 'A calculating, patient tyrant who treats conquest and war as an enjoyable game and rewards loyal minions with autonomy.', 'High Lord Lesion (second-in-command, absolute mutual trust); Queen Salome (treated as an equal, trusted above his own demon lords).', 'The Confessor (his one feared foe); the Champions of Light.', 'The demonic supreme ruler of Wormwood''s Forces of Darkness, a wolf-bull-bat monstrosity who lost an eye to the Confessor and rules from the Mountain of Skulls.', 'Rifts Dimension Book 1: Wormwood p.142-143');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'high-lord-lesion', 'High Lord Lesion', NULL, 'High Lord of the Host; the Unholy''s second in command (pronounced Lee-zhen)', 'rifts', 'Host', NULL, 9, 'Miscreant', NULL, '11 feet (3.3 m)', '1100 pounds (500 kg)', '{"IQ":24,"ME":21,"MA":18,"PS":41,"PP":20,"PE":19,"PB":5,"Spd":26}', NULL, NULL, 3800, 600, 600, NULL, 17, '{"attacks":5,"initiative":1,"strike":6,"parry":5,"dodge":5,"pull":4,"roll":4}', 'Speed also 70 flying (~50 mph/80 km). +1 save vs psionics, +3 to save vs spell/illusionary magic, +2 to save vs circle magic, +10 to save vs horror factor. Critical strike on unmodified 18-20; hands/finger claws used as paired weapons. Cannot swim, sinks like a rock and drowns; holy water (not normal water) burns him like it does vampires, so he avoids water and dislikes rain. As second-in-command he also has the Black Abyss power (see the Unholy''s entry). Combat abilities and natural abilities are printed as ''Standard; same as all the Host.''', NULL, 'R.C.C. Skills: Standard (same as the Host).', 'Standard; same as all the Host (10-13 foot wolf-headed, bull-horned, bat-winged giant).', 'Special ability to warp and shape nature and power over Wormwood, standard/same as all Host. As second-in-command he also holds the Black Abyss dimensional pocket power (see the Unholy''s entry: 500 P.P.E., limited to the leader and his second-in-command).', 'Master psionic: astral projection, clairvoyance, empathy, telepathy, see aura, total recall, detect psionics, psychic diagnosis, psychic surgery (used to torture), healing touch, deaden pain, sleep, mind block auto-defense, group mind block, bio-manipulation, empathic transmission, hypnotic suggestion, mentally possess others, psi-sword, psi-shield.', NULL, NULL, 'A lesser rune dagger and a scepter similar to the Unholy''s (see attacks): spell gem of dimensions (greater), three lesser energy cells (25 P.P.E. each), two lesser energy cells (10 P.P.E. each, 95 P.P.E. total), a psi-booster blood stone (greater). Body Armor: grey resin shoulder plates and arm bands, worn as ornamentation only.', 'A fortune worth 100 million credits.', 'Loves war and conflict, has an excellent head for strategy and organization, and is a master of espionage, mind control and deception; completely loyal to the Unholy.', 'The Unholy (mutual, absolute trust); Queen Salome (mentee and closest friend).', 'The Cathedral''s high command (target of his infiltration and espionage).', 'The Unholy''s most trusted lieutenant, a masterful strategist who runs the day-to-day administration of the demon empire and its spy networks.', 'Rifts Dimension Book 1: Wormwood p.143-144');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'lord-krikton', 'Lord Krikton', NULL, 'Master of Parasites (pronounced Krick-ton)', 'rifts', 'Host', NULL, 8, 'Diabolic', NULL, '13 feet tall (3.96 m)', '1000 pounds (450 kg)', '{"IQ":25,"ME":17,"MA":19,"PS":36,"PP":20,"PE":22,"PB":2,"Spd":22}', NULL, NULL, 4400, 800, 700, NULL, 17, '{"attacks":5,"initiative":1,"strike":9,"parry":8,"dodge":7,"pull":4,"roll":4}', '+11 on all skills, including secondary skills. Speed also 80 flying (~56 mph/90 km). +2 save vs psionics, +7 to save vs spell/illusionary magic, +6 to save vs all other magic, +10 to save vs horror factor. Critical strike on unmodified 18-20; hands/finger claws used as paired weapons. Cannot swim, sinks like a rock and drowns; holy water burns him like it does vampires. His control over Wormwood, symbiotes and parasites is stronger than most Host; his kingdom''s doorways are shaped like hungry maws with claw-shaped spires. 65% likelihood he would become Supreme Ruler if he destroyed the Unholy and Lesion (which he has not attempted).', NULL, 'R.C.C. Skills: minimal skill knowledge; can learn to read/write up to four languages and 1D4 other technical skills; knows basic math, literate in American, land navigation, streetwise, cryptography, forgery, palming, concealment, prowl, dance, horsemanship: monsters, all at 85% (not individually broken out here).', 'As all the Host. He looks worse than most of them: skull-like and gaunt, with sunken, bloodshot yellow eyes, blue-grey skin and white hair.', 'Ability to warp and shape nature, same as all Host, though his control over Wormwood, symbiotes and parasites is unusually strong.', 'Master psionic: astral projection, clairvoyance, empathy, telepathy, see aura, total recall, detect psionics, psychic diagnosis, psychic surgery (used to torture), healing touch, deaden pain, sleep, mind block auto-defense, group mind block, bio-manipulation, empathic transmission, hypnotic suggestion, mentally possess others, psi-sword, electrokinesis.', NULL, NULL, 'A particle beam rifle with three extra clips and a boom gun from Rifts Earth; a large jewel-encrusted sword (see attacks) set with a magic bio-booster crystal and spell gem of destruction (other gems worth 280,000 credits). Also 1D4 of every type of magic slime/potion/ointment, worms of blood, worms of mending, life force batteries, a private life force cauldron (about 1100 P.P.E. available at a time), and experimental parasites. Body Armor: None. Minions: roams with roughly 100 ticks, ~50 tangle/monster worms, two dozen flailers, leapers and battle wagons guarding his palace, two battlers, plus a half-dozen priests and a score of powerful parasites guarding his life force cauldron; his kingdom also holds thousands of human slaves and demonic minions.', 'A treasure worth 59+ million credits on Rifts Earth.', 'Greedy, envious, lecherous, sadistic and devious; festers with frustrated ambition to overthrow the Unholy and Lesion but cannot bring himself to act.', 'None true; his only ''friends'' are the parasites he has created.', 'Secretly envies and covets the destruction of the Unholy and High Lord Lesion; despises and belittles Queen Salome.', 'The Host''s third-ranking lord, a sadistic designer of giant mutant parasites who secretly covets the Unholy''s throne.', 'Rifts Dimension Book 1: Wormwood p.144-145');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'salome', 'Salome', NULL, 'Queen/Goddess of the Demon Goblins (pronounced Sah-low-m)', 'rifts', 'Human', 'Shifter', 10, 'Aberrant', NULL, 'Five feet ten inches tall (1.7 m)', '150 pounds (67.5 kg)', '{"IQ":15,"ME":21,"MA":20,"PS":18,"PP":14,"PE":17,"PB":24,"Spd":13}', 59, 14, NULL, 163, 59, NULL, NULL, '{"attacks":4,"initiative":1,"strike":1,"parry":2,"dodge":2,"pull":4,"roll":4,"damage":2}', 'M.D.C. is by armor and symbiotes only (she is human): 155 M.D.C. total, scale mail 75 M.D.C. plus a chest wrap crawler providing an additional 80 M.D.C. (which regenerates). Horror Factor printed as ''Not applicable.'' +4 to strike with a sword, +5 to parry with a sword, +2 S.D.C. damage, critical strike on unmodified 19-20, Judo-style body throw (1D6 S.D.C.), kick attack (1D6). +4 save vs magic, +3 save vs psionics, +1 save vs poison, +7 save vs horror factor. 60% to evoke feelings of trust or intimidation, 70% to charm and impress. Shifter Abilities: dimensional rift home, sense rifts, and others (see Rifts RPG pp.87-89).', '[{"name":"Language: American","pct":98},{"name":"Language: Dragonese","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: Demongogian","pct":70},{"name":"Literacy: American","pct":85},{"name":"Literacy: Dragonese","pct":85}]', 'O.C.C. Skills of Note (all at 10th level, no percentages printed): Hand to hand: basic, astronomy, basic math, lore: demon, lore: faerie, land navigation, wilderness survival, intelligence, dance, computer operation, pilot motorcycle, pilot hovercycle, horsemanship.', NULL, 'Sense magic, see aura, globe of daylight, call lightning, fire ball, circle of fire, levitate, float in air, fly like the eagle, breathe without air, climb, concealment, chameleon, shadow meld, time slip, teleport: lesser, teleport: superior, animate and control dead, turn dead, trance, exorcism, constrain being, control/enslave entity, summon and control canines, summon and control lesser beings, summon entity, create mummy, create golem, protection circle: simple and superior, close rift and dimensional portal/rift.', 'Minor Psionic: telepathy, speed reading.', NULL, NULL, 'A vibro-knife, vibro-sword, Wilk''s laser pistol with six extra E-clips, a Splugorth psi-interrogator, a staff of pacification, and an Impaler rune sword (see attacks; her favorite weapon). Symbiotic Organisms (Wormwood): booster claw, chest wrap crawler, finder crystal, null slime, stasis slime, restoration slime; also has access to High Lord Lesion''s life force batteries, life force cauldron, and magic slime potions/ointments (a coveted control gem was stolen back by Lazarus Vespers). Gold-plated forearm plate on her right arm: mini-healing stone (heals 4D6, three times), four robin egg-size energy cells (40 P.P.E. total), the Eye of Wormwood (greater crystal); also a basketball-size energy crystal (180 P.P.E.) kept on a pedestal in her lair. Splugorth/Atlantis symbiotes: 2D4 mystic leeches, 2D4 zombitrons, 1D4 lobee-optos, 1D4 pathic healers, 1D4 doses of aerobes, 1D4 doses of plastirobes.', 'A treasure in gems, gold and other valuables worth 40+ million credits on Rifts Earth, plus her rune sword and other magic items.', 'Ambitious, cunning, and ruthless, yet bound by her own twisted code of honor and lingering loyalty to old friends.', 'High Lord Lesion (mentor and closest friend); the Unholy (trusts her more than his own demon brothers); the demon goblins (adore her as queen/goddess); a pair of dimensional ghouls, three lasae demons, one malignous, and 1D4+2 demon goblin assassins (8th level) as personal minions. Plus another 3D4 demon goblins (4th-8th level) always within earshot', 'Lazarus Vespers (old friend turned adversary, love/hate relationship); Lord Krikton (despises her as ''Lesion''s lap dog''); the Champions of Light.', 'A power-hungry human shifter who rules the demon goblins as their queen and goddess, once a dear friend of Lazarus Vespers before the Splugorth broke her.', 'Rifts Dimension Book 1: Wormwood p.145-147');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'rock-great-horned-dragon', 'The Rock', NULL, 'Great Horned Dragon', 'rifts', 'Great Horned Dragon', 'Shifter and dimensional traveler', 9, 'Diabolic', NULL, NULL, NULL, '{"IQ":28,"ME":26,"MA":30,"PS":48,"PP":21,"PE":23,"PB":28,"Spd":50}', NULL, NULL, 6500, 1100, NULL, NULL, NULL, NULL, 'Speed also 130 (90 mph/148 km) flying. Female. Has made Rock Ridge her home for the last 139 years, conducting experiments in magic, torture and dimensional rifting/summoning; an expert in summoning supernatural monsters.', NULL, NULL, NULL, 'Shifter and dimensional traveler (9th level); an expert in summoning supernatural monsters and dimensional rifting.', NULL, NULL, NULL, 'Valuables of Note: one million credits worth of gems, jewelry, gold, body armor and miscellaneous equipment; exact magic items, if any, left to the Game Master.', 'One million credits worth of gems, jewelry, gold, body armor and equipment (exact magic items left to the G.M.).', 'Devious and cruel; loves confrontations with heroes and adventurers.', 'The Unholy (ally, main defender of Rock Ridge); He Who Seeks, a goqua (old friend and travelling companion); the Defenders of Rock Ridge (10 poltergeist entities, 4 harpies, 2 tectonic entities, 1 manticore, 1 Baal-rog, 1 Goqua [10th level]).', 'Atlantean undead slayers (whose wrath she originally fled).', 'An evil adult Great Horned Dragon who found Wormwood by accident while fleeing Atlantean undead slayers, and now rules Rock Ridge as an ally of the Unholy.', 'Rifts Dimension Book 1: Wormwood p.153-154');

