  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('thraxus', 'anshurr', 'trader-smythers', 'kreeghor-emperor', 'borshenko', 'auntie', 'murray', 'bug-vacuum-wasp', 'laurana', 'tiny-tim', 'confessor', 'lazarus-vespers', 'dorsey-pentecost', 'unholy', 'high-lord-lesion', 'lord-krikton', 'salome', 'rock-great-horned-dragon');

